mapper.select:
SELECT ri.id, ri.route_id, ri.day_number, ri.sort_order, ri.attraction_id, ri.suggested_duration, ri.transport_method, ri.note, a.name AS attraction_name, a.cover_image AS attraction_cover, a.description AS attraction_description, a.longitude AS attraction_longitude, a.latitude AS attraction_latitude, a.address AS attraction_address FROM route_items ri LEFT JOIN attractions a ON ri.attraction_id = a.id AND a.deleted = 0 WHERE ri.route_id IN
#{rid}
ORDER BY ri.route_id ASC, ri.day_number ASC, ri.sort_order ASC
